mod bookmark;
pub fn origin_label(text:&str) -> Result<String,String> {
    let summary=bookmark::summarize(text)?;
    Ok(match summary.port {
        Some(port)=>format!("{}:{}",summary.host,port),
        None=>summary.host,
    })
}

